Röviden: Az alábbiakban komplett, használatra kész backend (Nim) és frontend (HTML) vázat adok egy “chat + DeepSearch” alkalmazáshoz, amelyik a Cerebras gptoss120b modellt streamelve hívja (max 65 536 kimeneti token), és az Exa “fast” keresést integrálja az új “fast” típus szerint. A backend HTTPSen, helyes TLSwrap mellett kommunikál, SSE streamet bont, és külön “DeepSearch” gombbal indít ügynök módú (agent) mélykutatást, amely Exa találatokat beemel és a gptoss120bvel egy teljes magyar nyelvű, hosszú (min. 15 000 szavas) jelentést készít. [1][2][3][4][5][6]

 Fő elemek
 Nim backend: asynchttpserver alapú HTTP API, TLSes kimenő hívásokhoz asyncnet + wrapSocket, OpenAIkompatibilis Cerebras /v1/chat/completions streaming feldolgozás, Exa /search “type=fast” integráció. [6][5][1][3]
 Frontend: minimalista UI Appleszerű tipográfiával (a kapott CSSblokkot nem másoljuk teljes hosszban), chat input, “Küldés” és “DeepSearch” gomb; DeepSearch ügynök módot indít, mely Exaval keres, majd a gptoss120bvel összefűzi és egy teljes magyar kutatási jelentést generál. [4][3]
 Beállítások: CEREBRAS_API_KEY, EXA_API_KEY env változók; gptoss120b, stream=true, max_completion_tokens=65536, reasoning_effort=“low” a Cerebras dokumentáció alapján. [1][2]

 Megjegyzések a hálózatról és TLSről
 Nimben a tényleges TLShez newContext + wrapSocket szükséges az async sockethez; csak d:ssl flag nem elég. A kódmintában ezt javítom, és SNI/verify beállítást is adok. [5][7][8]
 SSE streamelés: a Cerebras OpenAIkompatibilis chat.completions streaming formátumot támogat; chunk.choices.delta.content jön, és [DONE]re kell lezárni. Egyes OSS szervereknél láttak “None” chunkokat, ezért védetten szűrjük az üres/None sztringeket. [1][9]

 Exa “fast” keresés
 Az Exa új “fast” típusához POST /search, body: {"query","type":"fast","numResults":...,"livecrawl":"never"} jó gyakorlat gyorsaságra. Az OpenAPI specifikáció alapján építjük a kérést; az auth Bearer EXA_API_KEY. [3][4]

 Projekt struktúra
 backend: main.nim (HTTP szerver + Cerebras stream + Exa keresés + agent pipeline)
 frontend: index.html (chat + DeepSearch UI)
 Makefile, config.nims (SSL, release, speed)
[6][5]

 Backend (main.nim)

nim
# main.nim
import std/[asynchttpserver, asyncdispatch, asyncnet, net, strutils, json, os, times, options]
# TLS
when defined(ssl):
  import std/ssl

# --- Konfigurációból ---
let CEREBRAS_HOST = "api.cerebras.ai"
let CEREBRAS_PORT = Port(443)
let CEREBRAS_PATH = "/v1/chat/completions"

let EXA_HOST = "api.exa.ai"
let EXA_PORT = Port(443)
let EXA_SEARCH_PATH = "/search"

proc nowIso(): string = times.format(now(), "yyyy-MM-dd'T'HH:mm:sszzz")

# --- Segéd: TLS wrap biztosan ---
proc connectTls(host: string, port: Port): Future[AsyncSocket] {.async.} =
  var s = newAsyncSocket()
  await s.connect(host, port)
  when defined(ssl):
    var ctx = newContext(verifyMode = CVerifyPeer, minVersion = TLSv1_2)
    # SNI beállítás
    s.wrapSocket(ctx, handshakeAsClient=true, serverName=host)
  return s

# --- SSE stream feldolgozás Cerebras-tól ---
proc cerebrasStreamChat(userMsg: string, sysPrompt = "", temperature = 0.09, top_p = 0.05,
                        maxTokens = 65536, reasoningEffort = "low"): Future[string] {.async.} =
  let apiKey = getEnv("CEREBRAS_API_KEY")
  if apiKey.len == 0:
    return "Hiányzó CEREBRAS_API_KEY."

  let sock = await connectTls(CEREBRAS_HOST, CEREBRAS_PORT)

  let body = %*{
    "model": "gpt-oss-120b",
    "messages": [
      {"role": "system", "content": sysPrompt},
      {"role": "user", "content": userMsg}
    ],
    "stream": true,
    "max_completion_tokens": maxTokens,
    "temperature": temperature,
    "top_p": top_p,
    "reasoning_effort": reasoningEffort
  }
  let bodyStr = $body

  var headers = "POST " & CEREBRAS_PATH & " HTTP/1.1\r\n" &
    "Host: " & CEREBRAS_HOST & "\r\n" &
    "Authorization: Bearer " & apiKey & "\r\n" &
    "Content-Type: application/json\r\n" &
    "Connection: keep-alive\r\n" &
    "Content-Length: " & $bodyStr.len & "\r\n\r\n"

  await sock.send(headers & bodyStr)

  # HTTP headerek átugrása
  while true:
    let line = await sock.recvLine()
    if line.len == 0: break

  var acc = newStringOfCap(8192)

  # SSE: soronként "data: {json}" vagy "data: [DONE]"
  while true:
    let line = await sock.recvLine()
    if line.len == 0: 
      # SSE üres sor blokk elválasztó; folytatás
      continue
    if line.startsWith("data:"):
      let data = line[5..^1].strip()
      if data == "[DONE]":
        break
      try:
        let chunk = parseJson(data)
        # OpenAI-kompatibilis delta:
        if chunk.hasKey("choices"):
          let ch = chunk["choices"][0]
          if ch.hasKey("delta"):
            let delta = ch["delta"]
            if delta.hasKey("content"):
              var piece = delta["content"].getStr()
              # Védjük ki az esetleges 'None' részeket (ismert OSS issue)
              if piece.len > 0 and piece != "None":
                acc.add(piece)
      except:
        discard
  sock.close()
  return acc

# --- Exa fast keresés ---
proc exaFastSearch(query: string; numResults = 25; livecrawl = "never"): Future[JsonNode] {.async.} =
  let apiKey = getEnv("EXA_API_KEY")
  if apiKey.len == 0:
    return %*{"error": "Hiányzó EXA_API_KEY"}

  let sock = await connectTls(EXA_HOST, EXA_PORT)
  let body = %*{
    "query": query,
    "type": "fast",
    "numResults": numResults,
    "livecrawl": livecrawl
  }
  let bodyStr = $body

  let req = "POST " & EXA_SEARCH_PATH & " HTTP/1.1\r\n" &
    "Host: " & EXA_HOST & "\r\n" &
    "Authorization: Bearer " & apiKey & "\r\n" &
    "Content-Type: application/json\r\n" &
    "Content-Length: " & $bodyStr.len & "\r\n" &
    "Connection: close\r\n\r\n" & bodyStr

  await sock.send(req)

  # HTTP headerek átugrása
  while true:
    let line = await sock.recvLine()
    if line.len == 0: break

  var response = ""
  while true:
    let chunk = await sock.recv(4096)
    if chunk.len == 0: break
    response.add(chunk)
  sock.close()

  try:
    return parseJson(response)
  except:
    return %*{"raw": response}

# --- Agent pipeline DeepSearch: Exa -> források összefűzése -> teljes magyar jelentés Cerebras-szal ---
proc deepResearchAgent(topic: string): Future[string] {.async.} =
  # 1) Exa gyors keresés sok találattal
  let search = await exaFastSearch(topic, numResults=100, livecrawl="never")
  # 2) Egyszerű kontextus extrakt: cím+url+snippet ha van
  var contextText = "Kutatási dátum: " & nowIso() & "\nTéma: " & topic & "\nForrások:\n"
  if search.kind == JObject and search.hasKey("results"):
    for r in search["results"].items:
      let title = if r.hasKey("title"): r["title"].getStr() else: ""
      let url = if r.hasKey("url"): r["url"].getStr() else: ""
      let snippet = if r.hasKey("text"): r["text"].getStr() else: (if r.hasKey("highlight"): r["highlight"].getStr() else: "")
      contextText.add("- " & title & " | " & url & "\n")
      if snippet.len > 0:
        contextText.add("  Kivonat: " & snippet[0 .. min(snippet.len-1, 500)] & "\n")
  else:
    contextText.add("Nincs strukturált eredmény vagy API hiba.\n")

  # 3) Kialakítunk egy ügynök rendszerpromptot magyar, szigorú követelménnyel (min 15k szó cél)
  let sysPrompt = """
Te egy autonóm kutatóügynök vagy, aki önállóan teljes körű magyar nyelvű szakmai kutatási jelentést készít egy megadott témáról.
Követelmények:
- Kizárólag magyarul írj.
- A jelentés legyen minimálisan kb. 15 000 szavas, fő részekkel: összefoglaló, hátterek, állapotfelmérés, módszertan, összehasonlítás, kockázatok, korlátok, nyitott kérdések, irányelvek, javaslatok, mellékletek.
- Használd fel a kapott forráslistát és kontextust, de a szöveg legyen eredeti, hivatkozásokat szövegközben említsd (pl. [Forrás: cím vagy domain]).
- Légy pontos, tárgyilagos, és strukturált. Készíts tartalomjegyzéket és részletes fejezeteket, alfejezeteket is.
- Térj ki definíciókra, fogalmi térképre, történeti háttérre, trendekre, mérőszámokra, módszertani keretekre, esettanulmányokra, implementációs útmutatóra, és jövőbeni kutatási irányokra.
- Nem szabad rövidíteni; a terjedelem és részletezettség elsődleges cél.
"""

  let userMsg = "Téma:\n" & topic & "\n\nForrás-kivonatok és linkek:\n" & contextText & "\nFeladat: Készíts teljes magyar nyelvű, nagyterjedelmű (min. 15 000 szavas) szintézist a fenti elvek alapján."

  # 4) Hosszú streaming generálás 65k tokennel
  let report = await cerebrasStreamChat(userMsg, sysPrompt=sysPrompt, temperature=0.1, top_p=0.05,
                                        maxTokens=65536, reasoningEffort="low")
  return report

# --- HTTP szerver végpontok ---
# POST /api/chat { "message": "..." }
# POST /api/deepsearch { "topic": "..." }
proc route(req: Request) {.async.} =
  if req.reqMethod == HttpPost and req.url.path == "/api/chat":
    let body = await req.body
    var msg = ""
    try:
      let j = parseJson(body)
      msg = j["message"].getStr()
    except:
      discard
    let reply = await cerebrasStreamChat(msg, sysPrompt="Mindig magyarul válaszolj.")
    await req.respond(Http200, %*{"reply": reply}.pretty)
    return

  if req.reqMethod == HttpPost and req.url.path == "/api/deepsearch":
    let body = await req.body
    var topic = ""
    try:
      let j = parseJson(body)
      topic = j["topic"].getStr()
    except:
      discard
    let bigReport = await deepResearchAgent(topic)
    await req.respond(Http200, %*{"report": bigReport}.pretty)
    return

  await req.respond(Http404, "Not Found")

proc main() {.async.} =
  var server = newAsyncHttpServer()
  server.listen(Port(8080))
  echo "Server on http://localhost:8080"
  while true:
    if server.shouldAcceptRequest():
      await server.acceptRequest(route)
    else:
      await sleepAsync(200)

waitFor main()



 Frontend (index.html)

html
<!DOCTYPE html>
<html lang="hu">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Chat + DeepSearch</title>
  <style>
    body { font-family: -apple-system, system-ui, Segoe UI, Roboto, Helvetica, Arial, sans-serif; margin: 0; background: #fafafa; color: #111; }
    header { position: sticky; top: 0; background: rgba(250,250,252,0.92); backdrop-filter: saturate(180%) blur(20px); padding: 12px 16px; border-bottom: 1px solid #eee; }
    main { max-width: 920px; margin: 0 auto; padding: 16px; }
    .row { display: flex; gap: 8px; margin-bottom: 8px; }
    textarea { flex: 1; padding: 12px; border: 1px solid #ddd; border-radius: 10px; resize: vertical; min-height: 80px; }
    button { padding: 10px 14px; border-radius: 10px; border: 1px solid #ddd; background: #fff; cursor: pointer; }
    button:hover { border-color: #bbb; }
    .out { white-space: pre-wrap; background: #fff; border: 1px solid #eee; padding: 12px; border-radius: 12px; min-height: 120px; }
    .section { margin-top: 16px; }
    .muted { color: #666; font-size: 12px; }
  </style>
</head>
<body>
  <header>
    <strong>Agent Chat</strong>
  </header>
  <main>
    <div class="section">
      <div class="row">
        <textarea id="msg" placeholder="Írj egy üzenetet magyarul..."></textarea>
      </div>
      <div class="row">
        <button id="send">Küldés</button>
        <button id="deep">DeepSearch</button>
      </div>
      <div class="section">
        <div class="muted">Kimenet:</div>
        <div id="out" class="out"></div>
      </div>
    </div>
  </main>

<script>
const out = document.getElementById('out');

async function postJSON(url, data) {
  const r = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data)
  });
  if (!r.ok) throw new Error('Hiba: ' + r.status);
  return await r.json();
}

document.getElementById('send').addEventListener('click', async () => {
  const msg = document.getElementById('msg').value.trim();
  if (!msg) return;
  out.textContent = 'Gondolkodom...';
  try {
    const res = await postJSON('/api/chat', { message: msg });
    out.textContent = res.reply || '(nincs válasz)';
  } catch (e) {
    out.textContent = 'Hiba: ' + e.message;
  }
});

document.getElementById('deep').addEventListener('click', async () => {
  const topic = document.getElementById('msg').value.trim();
  if (!topic) return;
  out.textContent = 'Mélykutatás folyamatban (Exa + GPT-OSS-120B)... ez eltarthat.';
  try {
    const res = await postJSON('/api/deepsearch', { topic });
    out.textContent = res.report || '(nincs jelentés)';
  } catch (e) {
    out.textContent = 'Hiba: ' + e.message;
  }
});
</script>
</body>
</html>



